#!/usr/bin/env node
/**
 * Seed the Debugging Arena (SFCode parity, Phase B): problems that start from
 * a broken script the learner has to fix.
 *
 *     npm -w dwcode-server run seed:debugging -- --check     # compiler only, no database
 *     npm -w dwcode-server run seed:debugging -- --dry-run   # + report what would be inserted
 *     npm -w dwcode-server run seed:debugging                # insert the missing ones
 *
 * SAFETY
 *  - Every expectation is GENERATED by running the reviewed fix through the
 *    real compiler (CLAUDE.md: never hand-write expectedOutput).
 *  - A problem is rejected unless the fix passes all of its cases AND the
 *    broken starter fails at least one — otherwise it is not a debugging
 *    problem. Rejected problems are reported and the run exits non-zero.
 *  - Insert-only and idempotent: an existing slug is never modified.
 */
import { readFileSync } from "node:fs";
import mongoose from "mongoose";
import { DIFFICULTY_TIERS } from "@dwcode/shared";
import { COMPILER_SERVICE_URL, COMPILER_URL, normalizeOutput, runScript } from "./lib/compiler.mjs";

const CHECK_ONLY = process.argv.includes("--check");
const DRY_RUN = CHECK_ONLY || process.argv.includes("--dry-run");
const SPECS = JSON.parse(readFileSync(new URL("./data/debugging-problems.json", import.meta.url), "utf8"));
const TIERS = new Set(DIFFICULTY_TIERS.map((t) => t.id));

async function outputOrError(script, input) {
  try {
    return { ok: true, output: await runScript(script, input) };
  } catch (err) {
    return { ok: false, output: `<compiler error: ${err instanceof Error ? err.message : String(err)}>` };
  }
}

/** Build the problem document, or the reason it cannot be one. */
async function build(spec) {
  if (!TIERS.has(spec.difficulty)) return { reason: `unknown difficulty "${spec.difficulty}"` };
  const inputs = [...spec.examples.map((e) => e.input), ...spec.tests, ...spec.hidden];
  const expected = [];
  for (const input of inputs) {
    const run = await outputOrError(spec.solution, input);
    if (!run.ok) return { reason: `the fix fails on ${input}: ${run.output}` };
    expected.push(run.output);
  }
  let starterFails = false;
  for (let i = 0; i < inputs.length && !starterFails; i++) {
    const run = await outputOrError(spec.starterCode, inputs[i]);
    starterFails = !run.ok || normalizeOutput(run.output) !== normalizeOutput(expected[i]);
  }
  if (!starterFails) return { reason: "the broken starter already passes every case" };

  const e = spec.examples.length;
  const t = spec.tests.length;
  return {
    doc: {
      title: spec.title,
      slug: spec.slug,
      difficulty: spec.difficulty,
      category: "Debugging",
      tags: ["debugging", spec.bug],
      description: spec.description,
      examples: spec.examples.map((ex, i) => ({ input: ex.input, output: expected[i], explanation: ex.explanation })),
      constraints: [],
      starterCode: spec.starterCode,
      testCases: spec.tests.map((input, i) => ({ input, expectedOutput: expected[e + i] })),
      hiddenTestCases: spec.hidden.map((input, i) => ({ input, expectedOutput: expected[e + t + i] })),
      solution: spec.solution,
      hints: spec.hints,
      createdByAI: false,
      createdBy: "",
      createdAt: new Date(),
    },
  };
}

async function main() {
  console.log(`${CHECK_ONLY ? "CHECK" : DRY_RUN ? "DRY RUN" : "LIVE RUN"} — compiler: ${COMPILER_SERVICE_URL || COMPILER_URL}\n`);
  const built = [];
  let failed = 0;
  for (const spec of SPECS) {
    const result = await build(spec);
    if (result.reason) {
      failed++;
      console.log(`  REJECT  ${spec.slug}: ${result.reason}`);
    } else {
      built.push(result.doc);
      console.log(`  ok      ${spec.slug} (${result.doc.examples.length + result.doc.testCases.length + result.doc.hiddenTestCases.length} cases)`);
    }
  }
  if (CHECK_ONLY) {
    process.exitCode = failed ? 1 : 0;
    return;
  }

  if (!process.env.MONGODB_URI) throw new Error("MONGODB_URI is not set (server/.env).");
  await mongoose.connect(process.env.MONGODB_URI, { autoIndex: false });
  const problems = mongoose.connection.db.collection("problems");
  let inserted = 0;
  for (const doc of built) {
    if (await problems.findOne({ slug: doc.slug }, { projection: { _id: 1 } })) {
      console.log(`  exists  ${doc.slug}`);
      continue;
    }
    if (DRY_RUN) {
      console.log(`  would insert ${doc.slug}`);
      continue;
    }
    await problems.insertOne(doc);
    inserted++;
    console.log(`  inserted ${doc.slug}`);
  }
  await mongoose.disconnect();
  console.log(`\n${DRY_RUN ? "Nothing written." : `Inserted ${inserted}.`}${failed ? ` ${failed} rejected.` : ""}`);
  process.exitCode = failed ? 1 : 0;
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
